insert into activities (id, domain, age_band, title, why, duration_minutes, duration_label, materials, instructions, benefit, source) values
  ('chest-tummy-time-m0_3', 'motor'::domain, 'm0_3'::age_band, 'Chest Tummy Time', 'A gentle activity that supports head and neck control.', 4, '2–5 min', 'None', 'Recline on a sofa or propped-up pillows, baby face-down on your bare chest, one hand supporting their back. Get face-to-face: your face is their strongest motivation to lift their head.', 'In these first months your baby is working on the very first physical task of life: holding their own head steady and learning that their body belongs to them. Repetition matters far more than variety now, so the same thing tomorrow is exactly right.', 'AAP Safe Sleep and Tummy Time; WHO Motor Development; IAP'),
  ('floor-tummy-time-m0_3', 'motor'::domain, 'm0_3'::age_band, 'Floor Tummy Time', 'A gentle activity that supports head and neck control.', 4, '2–5 min', 'Muslin cloth', 'Lay baby face-down on a firm, clean surface. Place a rolled muslin under chest to ease the lift. Start 2 min and add 1 min per week.', 'In these first months your baby is working on the very first physical task of life: holding their own head steady and learning that their body belongs to them. Keep it short and stop as soon as your baby looks away or fusses. Their attention span is measured in moments, and that is normal.', 'AAP Safe Sleep and Tummy Time; WHO Motor Development; IAP'),
  ('bicycle-legs-m0_3', 'motor'::domain, 'm0_3'::age_band, 'Bicycle Legs', 'A calm, close activity for building leg strength and kicking.', 4, '3–5 min', 'None', 'Lay baby on back; hold ankles gently and move legs in slow cycling motions. Say ''pedal, pedal'' rhythmically while maintaining eye contact.', 'Babies this age cannot yet control their movements, so this is about giving the body the right opportunities rather than teaching a skill. Repetition matters far more than variety now, so the same thing tomorrow is exactly right.', 'ICMR-NIN Dietary Guidelines for Indians; IAP Infant and Young Child Feeding; IAP'),
  ('arm-stretch-midline-m0_3', 'motor'::domain, 'm0_3'::age_band, 'Arm Stretch Midline', 'A calm, close activity for building head and neck control.', 4, '3–5 min', 'None', 'Gently hold baby''s forearms, slowly extend arms outward, then bring hands together at midline over chest. Repeat 5 times each side.', 'In these first months your baby is working on the very first physical task of life: holding their own head steady and learning that their body belongs to them. Repetition matters far more than variety now, so the same thing tomorrow is exactly right.', 'WHO Motor Development Milestones; AAP Safe Sleep and Tummy Time; IAP'),
  ('visual-tracking-card-m0_3', 'motor'::domain, 'm0_3'::age_band, 'Visual Tracking Card', 'A gentle activity that supports visual tracking with head movement.', 4, '3–5 min', 'Paper with B&W pattern', 'Hold a high-contrast B&W card 25 cm from baby''s face. Move it slowly left then right. Let eyes find it before you move again.', 'Every small movement now is building the neck, shoulder and trunk strength that rolling and sitting will later depend on. Keep it short and stop as soon as your baby looks away or fusses. Their attention span is measured in moments, and that is normal.', 'WHO Motor Development Milestones; AAP Safe Sleep and Tummy Time; IAP'),
  ('supported-upright-hold-m0_3', 'motor'::domain, 'm0_3'::age_band, 'Supported Upright Hold', 'A gentle activity that supports early trunk support.', 4, '3–5 min', 'None', 'Hold baby upright against your shoulder and let them practice holding their head for 10–15 seconds. Support gently: don''t grip.', 'In these first months your baby is working on the very first physical task of life: holding their own head steady and learning that their body belongs to them. At this age your only job is to offer it warmly and let your baby respond however they do; there is nothing to achieve and nothing to get right.', 'WHO Motor Development Milestones; AAP Safe Sleep and Tummy Time; IAP'),
  ('leg-kicking-scarf-m0_3', 'motor'::domain, 'm0_3'::age_band, 'Leg Kicking Scarf', 'A simple everyday moment that supports leg strength and kicking.', 8, '5–10 min', 'Light scarf or cloth', 'Hold a light scarf 15 cm above baby''s feet while they lie on back. Let them discover kicking makes it move: first cause-effect feedback.', 'In these first months your baby is working on the very first physical task of life: holding their own head steady and learning that their body belongs to them. At this age your only job is to offer it warmly and let your baby respond however they do; there is nothing to achieve and nothing to get right.', 'WHO Motor Development Milestones; AAP Safe Sleep and Tummy Time; IAP'),
  ('side-lying-practice-m0_3', 'motor'::domain, 'm0_3'::age_band, 'Side-Lying Practice', 'A gentle activity that supports early rolling.', 8, '5–10 min', 'Rolled towel', 'Place baby on their side with a rolled towel tucked behind their back for support. Alternate sides each session; 5 min per side.', 'Every small movement now is building the neck, shoulder and trunk strength that rolling and sitting will later depend on. At this age your only job is to offer it warmly and let your baby respond however they do; there is nothing to achieve and nothing to get right.', 'WHO Motor Development Milestones; AAP Safe Sleep and Tummy Time; IAP'),
  ('grip-my-finger-m0_3', 'motor'::domain, 'm0_3'::age_band, 'Grip My Finger', 'A calm, close activity for building reflexive grasp.', 4, '3–5 min', 'None', 'Place your index finger in baby''s palm and let the grasp reflex close around it. Gently tug to stimulate the grip.', 'Your baby''s hands are mostly working on reflex at this stage, and this gently invites them to open, feel and eventually grasp on purpose. Keep it short and stop as soon as your baby looks away or fusses. Their attention span is measured in moments, and that is normal.', 'AOTA Early Development; AAP Developmental Milestones; IAP'),
  ('hand-massage-m0_3', 'motor'::domain, 'm0_3'::age_band, 'Hand Massage', 'A simple everyday moment that supports reflexive grasp.', 8, '5–10 min', 'Warm oil (optional)', 'With warm hands make small circular motions across each palm and each finger. Open fisted hands gently with thumb-stroke wrist to fingertips.', 'Before a baby can reach for anything they need to discover their hands exist, and this is part of that discovery. Keep it short and stop as soon as your baby looks away or fusses. Their attention span is measured in moments, and that is normal.', 'AOTA Early Development; AAP Developmental Milestones; IAP'),
  ('open-fist-m0_3', 'motor'::domain, 'm0_3'::age_band, 'Open Fist', 'A simple everyday moment that supports reflexive grasp.', 4, '3–5 min', 'None', 'When baby''s fists are clenched, gently stroke from wrist to fingertips along the back of the hand to encourage opening.', 'Before a baby can reach for anything they need to discover their hands exist, and this is part of that discovery. At this age your only job is to offer it warmly and let your baby respond however they do; there is nothing to achieve and nothing to get right.', 'AOTA Early Development; AAP Developmental Milestones; IAP'),
  ('bringing-hands-middle-m0_3', 'motor'::domain, 'm0_3'::age_band, 'Bringing Hands Middle', 'A gentle activity that supports reflexive grasp.', 4, '3–5 min', 'None', 'Gently bring baby''s hands together at the centre of their chest. Hold 3 seconds, release. This builds bilateral brain coordination.', 'Before a baby can reach for anything they need to discover their hands exist, and this is part of that discovery. Keep it short and stop as soon as your baby looks away or fusses. Their attention span is measured in moments, and that is normal.', 'AOTA Early Development; AAP Developmental Milestones; IAP'),
  ('gentle-wrist-turns-m0_3', 'motor'::domain, 'm0_3'::age_band, 'Gentle Wrist Turns', 'A calm, close activity for building reflexive grasp.', 4, '3–5 min', 'None', 'Hold baby''s forearm steady and gently rotate the wrist in small circles, 5 times each direction on each hand.', 'Hand movements are still involuntary now, so this is about sensation and awareness rather than skill. Keep it short and stop as soon as your baby looks away or fusses. Their attention span is measured in moments, and that is normal.', 'AOTA Early Development; AAP Developmental Milestones; IAP'),
  ('holding-soft-toy-m0_3', 'motor'::domain, 'm0_3'::age_band, 'Holding Soft Toy', 'A gentle activity that supports reflexive grasp.', 4, '3–5 min', 'Small soft cloth roll', 'Place a small rolled cloth in baby''s palm. Note how long the grasp reflex holds it and whether they bring it toward their mouth.', 'Before a baby can reach for anything they need to discover their hands exist, and this is part of that discovery. Keep it short and stop as soon as your baby looks away or fusses. Their attention span is measured in moments, and that is normal.', 'AOTA Early Development; AAP Developmental Milestones; IAP'),
  ('narrate-every-routine-m0_3', 'communication'::domain, 'm0_3'::age_band, 'Narrate Every Routine', 'A gentle activity that supports early vocal play.', null, 'Ongoing', 'None', 'Talk through every nappy change, feed, and bath. ''Now I''m lifting your legs. This might feel cool.'' Tone matters more than words.', 'Long before your baby says a word, they are learning the rhythm, pitch and melody of your language, and that learning happens now. Keep it short and stop as soon as your baby looks away or fusses. Their attention span is measured in moments, and that is normal.', 'AAP Safe Sleep Guidance; IAP; IAP'),
  ('lori-song-m0_3', 'communication'::domain, 'm0_3'::age_band, 'Lori / Song', 'A calm, close activity for building rhythm and melody of language.', 8, '5–10 min', 'None', 'Sing one consistent song at the same time each day. Repetition builds a neural safety pattern. Same song, same voice, every day.', 'Your voice is the most important sound in your baby''s world, and every bit of talk builds the foundation for later language. At this age your only job is to offer it warmly and let your baby respond however they do; there is nothing to achieve and nothing to get right.', 'ASHA Speech and Language Milestones; Harvard Center on the Developing Child (Serve and Return); IAP'),
  ('sound-baby-makes-m0_3', 'communication'::domain, 'm0_3'::age_band, 'Sound Baby Makes', 'A gentle activity that supports early vocal play.', 8, '5–10 min', 'None', 'When baby makes any vowel sound, mirror it back exactly. Pause 10 full seconds before speaking again: that gap is the lesson.', 'Babies absorb the patterns of speech months before they can produce any of it, which is why talking to them matters so early. Keep it short and stop as soon as your baby looks away or fusses. Their attention span is measured in moments, and that is normal.', 'ASHA Speech and Language Milestones; Harvard Center on the Developing Child (Serve and Return); IAP'),
  ('wait-and-respond-talking-game-m0_3', 'communication'::domain, 'm0_3'::age_band, 'Wait-and-Respond Talking Game', 'A simple everyday moment that supports early vocal play.', 8, '5–10 min', 'None', 'After speaking or making a sound, count to 10 silently before responding again. You are teaching conversation structure.', 'Long before your baby says a word, they are learning the rhythm, pitch and melody of your language, and that learning happens now. Repetition matters far more than variety now, so the same thing tomorrow is exactly right.', 'ASHA Speech and Language Milestones; Harvard Center on the Developing Child (Serve and Return); IAP'),
  ('name-recognition-distance-m0_3', 'communication'::domain, 'm0_3'::age_band, 'Name Recognition Distance', 'A calm, close activity for building early vocal play.', 4, '3–5 min', 'None', 'Call baby''s name from 1 metre away (not from directly in front). Watch for eyes or head turning toward the sound.', 'Long before your baby says a word, they are learning the rhythm, pitch and melody of your language, and that learning happens now. At this age your only job is to offer it warmly and let your baby respond however they do; there is nothing to achieve and nothing to get right.', 'ASHA Speech and Language Milestones; Harvard Center on the Developing Child (Serve and Return); IAP'),
  ('sound-exploration-m0_3', 'communication'::domain, 'm0_3'::age_band, 'Sound Exploration', 'A simple everyday moment that supports early vocal play.', 4, '3–5 min', 'Household objects', 'Introduce one new household sound daily: wooden spoon on pot, rustling paper, running water. Watch how baby stills and locates.', 'Babies absorb the patterns of speech months before they can produce any of it, which is why talking to them matters so early. At this age your only job is to offer it warmly and let your baby respond however they do; there is nothing to achieve and nothing to get right.', 'ASHA Speech and Language Milestones; Harvard Center on the Developing Child (Serve and Return); IAP'),
  ('sing-song-baby-talk-m0_3', 'communication'::domain, 'm0_3'::age_band, 'Sing-Song Baby Talk', 'A gentle activity that supports rhythm and melody of language.', null, 'Ongoing', 'None', 'Use a slightly higher pitch and slower pace than normal when talking to baby. This is biologically optimal for infant language processing.', 'Your voice is the most important sound in your baby''s world, and every bit of talk builds the foundation for later language. Keep it short and stop as soon as your baby looks away or fusses. Their attention span is measured in moments, and that is normal.', 'ASHA Speech and Language Milestones; Harvard Center on the Developing Child (Serve and Return); IAP'),
  ('read-aloud-m0_3', 'communication'::domain, 'm0_3'::age_band, 'Read Aloud', 'A gentle activity that supports exposure to language patterns.', 8, '5–10 min', 'Any book or text', 'Read any book, recipe, or message aloud to baby. The vocabulary range and rhythm matter: comprehension is irrelevant at this stage.', 'Babies absorb the patterns of speech months before they can produce any of it, which is why talking to them matters so early. Keep it short and stop as soon as your baby looks away or fusses. Their attention span is measured in moments, and that is normal.', 'ASHA Speech and Language Milestones; Harvard Center on the Developing Child (Serve and Return); IAP'),
  ('high-contrast-cards-m0_3', 'cognitive'::domain, 'm0_3'::age_band, 'High-Contrast Cards', 'A gentle activity that supports visual attention and tracking.', 4, '3–5 min', 'Paper with B&W pattern', 'Hold a black-and-white card 25 cm from baby''s face. Let them fixate 10 seconds before moving slowly left. Newborn vision peaks at this distance.', 'Newborn vision and attention are still developing, and this gives them exactly the kind of input that helps them along. At this age your only job is to offer it warmly and let your baby respond however they do; there is nothing to achieve and nothing to get right.', 'Harvard Center on the Developing Child; Zero to Three; IAP'),
  ('face-gazing-m0_3', 'cognitive'::domain, 'm0_3'::age_band, 'Face Gazing', 'A simple everyday moment that supports face recognition.', 7, '5–8 min', 'None', 'Hold your face 20–30 cm from baby''s. Make one slow exaggerated expression and hold it. Wait 10 seconds for their response.', 'Your baby''s brain is building its very first expectations about the world, mostly through what they see and hear repeatedly. Keep it short and stop as soon as your baby looks away or fusses. Their attention span is measured in moments, and that is normal.', 'Harvard Center on the Developing Child; Zero to Three; IAP'),
  ('mirror-gazing-m0_3', 'cognitive'::domain, 'm0_3'::age_band, 'Mirror Gazing', 'A gentle activity that supports visual attention and tracking.', 4, '3–5 min', 'Any mirror', 'Hold a small unbreakable mirror 25 cm from baby. They won''t recognise themselves yet, but the responsive face is deeply engaging.', 'At this stage thinking looks like looking: attention, recognition and noticing what is familiar. At this age your only job is to offer it warmly and let your baby respond however they do; there is nothing to achieve and nothing to get right.', 'Harvard Center on the Developing Child (Serve and Return); IAP'),
  ('disappearing-face-peek-m0_3', 'cognitive'::domain, 'm0_3'::age_band, 'Disappearing Face Peek', 'A simple everyday moment that supports face recognition.', 8, '5–10 min', 'None', 'Cover your face with your hands. Hold 3 seconds. Reveal warmly. Very early object permanence and social anticipation practice.', 'Your baby''s brain is building its very first expectations about the world, mostly through what they see and hear repeatedly. Keep it short and stop as soon as your baby looks away or fusses. Their attention span is measured in moments, and that is normal.', 'Piagetian developmental framework; Harvard Center on the Developing Child; IAP'),
  ('light-shadow-m0_3', 'cognitive'::domain, 'm0_3'::age_band, 'Light Shadow', 'A calm, close activity for building visual attention and tracking.', 4, '3–5 min', 'Window or lamp', 'Carry baby toward a window or lamp. Let them observe light change as you move closer and further. Narrate: ''Bright! Now darker.''', 'Newborn vision and attention are still developing, and this gives them exactly the kind of input that helps them along. Repetition matters far more than variety now, so the same thing tomorrow is exactly right.', 'Harvard Center on the Developing Child; Zero to Three; IAP'),
  ('b-w-pattern-book-m0_3', 'cognitive'::domain, 'm0_3'::age_band, 'B&W Pattern Book', 'A calm, close activity for building visual attention and tracking.', 7, '5–8 min', 'High-contrast book or printed pages', 'Hold a high-contrast picture book 25 cm from baby. Spend 20–30 seconds on each page before turning. One page can hold attention this age.', 'Newborn vision and attention are still developing, and this gives them exactly the kind of input that helps them along. Repetition matters far more than variety now, so the same thing tomorrow is exactly right.', 'Harvard Center on the Developing Child; Zero to Three; IAP'),
  ('skin-to-skin-hold-m0_3', 'social_emotional'::domain, 'm0_3'::age_band, 'Skin-to-Skin Hold', 'A calm, close activity for building comfort and co-regulation.', 23, '15–30 min', 'None', 'Undress baby to nappy and hold against bare chest tummy-to-tummy. Cover both lightly. Regulates temperature, cortisol, and heart rate.', 'Your baby cannot calm themselves yet, so being soothed by you is how their nervous system learns what calm feels like. At this age your only job is to offer it warmly and let your baby respond however they do; there is nothing to achieve and nothing to get right.', 'AAP Safe Sleep Guidance; IAP; IAP'),
  ('smile-mirroring-m0_3', 'social_emotional'::domain, 'm0_3'::age_band, 'Smile Mirroring', 'A gentle activity that supports early social connection.', 8, '5–10 min', 'None', 'When baby makes a mouth movement or social smile, reflect it back immediately and wait. You are teaching: my expression has social power.', 'This is the beginning of the relationship, and at this age closeness and responsiveness are the whole task. Keep it short and stop as soon as your baby looks away or fusses. Their attention span is measured in moments, and that is normal.', 'Harvard Center on the Developing Child (Attachment); Zero to Three; UNICEF Responsive Caregiving; IAP'),
  ('responsive-holding-m0_3', 'social_emotional'::domain, 'm0_3'::age_band, 'Responsive Holding', 'A calm, close activity for building comfort and co-regulation.', null, 'Ongoing', 'None', 'When baby cries, respond before escalation. Consistent early response builds the secure attachment base for all future relationships.', 'This is the beginning of the relationship, and at this age closeness and responsiveness are the whole task. Keep it short and stop as soon as your baby looks away or fusses. Their attention span is measured in moments, and that is normal.', 'ICMR-NIN Dietary Guidelines for Indians; IAP Infant and Young Child Feeding; IAP'),
  ('emotional-narration-m0_3', 'social_emotional'::domain, 'm0_3'::age_band, 'Emotional Narration', 'A simple everyday moment that supports comfort and co-regulation.', null, 'Ongoing', 'None', 'Name what you see: ''You look uncomfortable. Let me see what''s wrong.'' Labelling emotional states builds the circuits for self-regulation later.', 'Your baby cannot calm themselves yet, so being soothed by you is how their nervous system learns what calm feels like. Repetition matters far more than variety now, so the same thing tomorrow is exactly right.', 'Harvard Center on the Developing Child (Attachment); Zero to Three; UNICEF Responsive Caregiving; IAP'),
  ('caregiver-rotation-m0_3', 'social_emotional'::domain, 'm0_3'::age_band, 'Caregiver Rotation', 'A gentle activity that supports comfort and co-regulation.', 18, '15–20 min', 'None', 'Let each main caregiver hold baby skin-to-skin. Each person''s unique warmth and heartbeat is a distinct and valuable regulatory experience.', 'Your baby cannot calm themselves yet, so being soothed by you is how their nervous system learns what calm feels like. At this age your only job is to offer it warmly and let your baby respond however they do; there is nothing to achieve and nothing to get right.', 'Harvard Center on the Developing Child (Attachment); Zero to Three; UNICEF Responsive Caregiving; IAP'),
  ('calm-modelling-m0_3', 'social_emotional'::domain, 'm0_3'::age_band, 'Calm Modelling', 'A gentle activity that supports comfort and co-regulation.', 8, '5–10 min', 'None', 'When you feel anxious, slow your own breathing while holding baby. They sense and entrain to your nervous system state.', 'Your baby cannot calm themselves yet, so being soothed by you is how their nervous system learns what calm feels like. Repetition matters far more than variety now, so the same thing tomorrow is exactly right.', 'Harvard Center on the Developing Child (Attachment); Zero to Three; UNICEF Responsive Caregiving; IAP'),
  ('tel-maalish-m0_3', 'cognitive'::domain, 'm0_3'::age_band, 'Tel Maalish', 'A calm, close activity for building tactile input and body awareness.', 13, '10–15 min', 'Coconut or mustard oil', 'Warm oil in palms. Begin with legs: least sensitive. Long slow strokes hip to foot, then arms, back, head. Stimulates vagus nerve.', 'Sensory experience is how a newborn learns about their own body and the world around it. Repetition matters far more than variety now, so the same thing tomorrow is exactly right.', 'AYUSH Ministry guidance on infant massage; IAP; IAP'),
  ('feel-different-things-m0_3', 'cognitive'::domain, 'm0_3'::age_band, 'Feel Different Things', 'A gentle activity that supports tactile input and body awareness.', 7, '5–8 min', 'Household objects with varied textures', 'Gently touch different textures to baby''s palm and feet: soft cloth, smooth wood, cool spoon. Name each: ''Soft. Smooth. Cool.''', 'Your baby''s nervous system is learning to make sense of touch, sound and movement, and gentle input helps it organise. Repetition matters far more than variety now, so the same thing tomorrow is exactly right.', 'AOTA Sensory Integration; AAP Developmental Milestones; IAP'),
  ('outdoor-air-light-m0_3', 'cognitive'::domain, 'm0_3'::age_band, 'Outdoor Air Light', 'A gentle activity that supports visual processing.', 13, '10–15 min', 'None', 'Take baby outside for 10–15 min. Wind, natural light, birdsong, and temperature variation are multi-sensory inputs no indoor space can replicate.', 'Sensory experience is how a newborn learns about their own body and the world around it. At this age your only job is to offer it warmly and let your baby respond however they do; there is nothing to achieve and nothing to get right.', 'AOTA Sensory Integration; AAP Developmental Milestones; IAP'),
  ('water-temperature-play-m0_3', 'cognitive'::domain, 'm0_3'::age_band, 'Water Temperature Play', 'A calm, close activity for building visual processing.', 8, '5–10 min', 'Water in containers', 'During bath, with baby always within arm''s reach, pour water at slightly different temperatures on hands. Narrate: ''Warm water now. A little cooler.'' Never leave baby unattended in water, even briefly.', 'Sensory experience is how a newborn learns about their own body and the world around it. Repetition matters far more than variety now, so the same thing tomorrow is exactly right.', 'AOTA Sensory Integration; AAP Developmental Milestones; IAP'),
  ('humming-chest-m0_3', 'cognitive'::domain, 'm0_3'::age_band, 'Humming Chest', 'A calm, close activity for building auditory processing.', 8, '5–10 min', 'None', 'Place baby against your chest and hum or sing. The physical vibration is felt across their whole body and is deeply calming.', 'Sensory experience is how a newborn learns about their own body and the world around it. Repetition matters far more than variety now, so the same thing tomorrow is exactly right.', 'AOTA Sensory Integration; AAP Developmental Milestones; IAP'),
  ('baby-s-hunger-signs-m0_3', 'social_emotional'::domain, 'm0_3'::age_band, 'Baby''s Hunger Signs', 'A calm, close activity for building feeding rhythm and hunger cues.', null, 'Ongoing', 'None', 'Learn early hunger cues: rooting, hand-to-mouth, stirring. Feed before crying. Responding to early cues builds baby''s signal-response trust.', 'Daily care routines are your baby''s first experience of predictability, and predictability is what makes them feel safe. Repetition matters far more than variety now, so the same thing tomorrow is exactly right.', 'IAP Infant Care Guidance; UNICEF Responsive Caregiving; IAP'),
  ('watching-tired-signs-m0_3', 'social_emotional'::domain, 'm0_3'::age_band, 'Watching Tired Signs', 'A calm, close activity for building sleep and wake rhythms.', null, 'Ongoing', 'None', 'Track awake time: 0–6 weeks = 45–60 min; 6–12 weeks = 60–90 min. Beginning sleep routine before overtiredness sets in improves settling.', 'At this age self-care is entirely done for your baby, and the value lies in how calm and consistent it feels. Keep it short and stop as soon as your baby looks away or fusses. Their attention span is measured in moments, and that is normal.', 'AAP Safe Sleep Guidance; IAP; IAP'),
  ('tummy-time-toy-m4_6', 'motor'::domain, 'm4_6'::age_band, 'Tummy Time Toy', 'A simple everyday moment that supports head and neck control.', 8, '5–10 min', 'Small toy or crinkle paper', 'Place an interesting toy just out of reach during tummy time. The motivation to lift and reach makes effort more sustained.', 'Every small movement now is building the neck, shoulder and trunk strength that rolling and sitting will later depend on. Keep it short and stop as soon as your baby looks away or fusses. Their attention span is measured in moments, and that is normal.', 'AAP Safe Sleep and Tummy Time; WHO Motor Development; IAP'),
  ('rolling-facilitation-m4_6', 'motor'::domain, 'm4_6'::age_band, 'Rolling Facilitation', 'A calm, close activity for building head and neck control.', 8, '5–10 min', 'None', 'In tummy time, gently rock baby''s hips toward one side. Give the nervous system the sensation of weight transfer needed for rolling.', 'In these first months your baby is working on the very first physical task of life: holding their own head steady and learning that their body belongs to them. At this age your only job is to offer it warmly and let your baby respond however they do; there is nothing to achieve and nothing to get right.', 'AAP Safe Sleep and Tummy Time; WHO Motor Development; IAP'),
  ('floor-roll-practice-m4_6', 'motor'::domain, 'm4_6'::age_band, 'Floor Roll Practice', 'A simple everyday moment that supports early rolling.', 7, '5–8 min', 'None', 'Place baby on their back. Gently cross one leg over the other and let momentum encourage rolling to the side. Celebrate any attempt.', 'Babies this age cannot yet control their movements, so this is about giving the body the right opportunities rather than teaching a skill. Repetition matters far more than variety now, so the same thing tomorrow is exactly right.', 'WHO Motor Development Milestones; AAP Safe Sleep and Tummy Time; IAP'),
  ('supported-sitting-m4_6', 'motor'::domain, 'm4_6'::age_band, 'Supported Sitting', 'A calm, close activity for building early trunk support.', 6, '3–8 min', 'None', 'Sit baby on your lap facing outward, hands loosely around their trunk. Let them feel the work: don''t over-support.', 'Every small movement now is building the neck, shoulder and trunk strength that rolling and sitting will later depend on. At this age your only job is to offer it warmly and let your baby respond however they do; there is nothing to achieve and nothing to get right.', 'WHO Motor Development Milestones; AAP Safe Sleep and Tummy Time; IAP'),
  ('prop-up-forearms-m4_6', 'motor'::domain, 'm4_6'::age_band, 'Prop Up Forearms', 'A simple everyday moment that supports head and neck control.', 8, '5–10 min', 'None', 'In tummy time, once baby pushes up on forearms, gently rock their hips side to side. This is the direct predecessor of rolling.', 'Babies this age cannot yet control their movements, so this is about giving the body the right opportunities rather than teaching a skill. Keep it short and stop as soon as your baby looks away or fusses. Their attention span is measured in moments, and that is normal.', 'AAP Safe Sleep and Tummy Time; WHO Motor Development; IAP'),
  ('against-my-hands-m4_6', 'motor'::domain, 'm4_6'::age_band, 'Against My Hands', 'A gentle activity that supports leg strength and kicking.', 7, '5–8 min', 'None', 'Hold your palms against baby''s feet while they lie on back. Let them push: this activates leg extensors used later for standing.', 'Babies this age cannot yet control their movements, so this is about giving the body the right opportunities rather than teaching a skill. Keep it short and stop as soon as your baby looks away or fusses. Their attention span is measured in moments, and that is normal.', 'WHO Motor Development Milestones; AAP Safe Sleep and Tummy Time; IAP'),
  ('bounce-lap-m4_6', 'motor'::domain, 'm4_6'::age_band, 'Bounce Lap', 'A calm, close activity for building leg strength and kicking.', 4, '3–5 min', 'None', 'Hold baby upright on your lap, supporting under arms, and let them bounce slightly. Vestibular input and leg strength combined.', 'In these first months your baby is working on the very first physical task of life: holding their own head steady and learning that their body belongs to them. Keep it short and stop as soon as your baby looks away or fusses. Their attention span is measured in moments, and that is normal.', 'WHO Motor Development Milestones; AAP Safe Sleep and Tummy Time; IAP'),
  ('tummy-time-mirror-m4_6', 'motor'::domain, 'm4_6'::age_band, 'Tummy Time Mirror', 'A gentle activity that supports head and neck control.', 8, '5–10 min', 'Any mirror', 'Prop an unbreakable mirror in front of baby during tummy time. Their own face is one of the strongest motivators to lift the head.', 'Babies this age cannot yet control their movements, so this is about giving the body the right opportunities rather than teaching a skill. Repetition matters far more than variety now, so the same thing tomorrow is exactly right.', 'AAP Safe Sleep and Tummy Time; WHO Motor Development; IAP'),
  ('reach-hanging-object-m4_6', 'motor'::domain, 'm4_6'::age_band, 'Reach Hanging Object', 'A calm, close activity for building hand awareness and early grasp.', 8, '5–10 min', 'Cloth, ribbon, or spoon on string', 'Hang a lightweight object (cloth, spoon) just above baby''s chest while they lie on back. Wait: let them discover swiping makes it move.', 'Your baby''s hands are mostly working on reflex at this stage, and this gently invites them to open, feel and eventually grasp on purpose. Repetition matters far more than variety now, so the same thing tomorrow is exactly right.', 'AOTA Early Development; AAP Developmental Milestones; IAP'),
  ('two-handed-grasp-m4_6', 'motor'::domain, 'm4_6'::age_band, 'Two-Handed Grasp', 'A simple everyday moment that supports reflexive grasp.', 8, '5–10 min', 'Wide rattle or soft ring', 'Offer a toy wider than one hand. Watch whether they use both hands together: bilateral integration milestone appearing around 4–5 months.', 'Before a baby can reach for anything they need to discover their hands exist, and this is part of that discovery. Repetition matters far more than variety now, so the same thing tomorrow is exactly right.', 'AOTA Early Development; AAP Developmental Milestones; IAP'),
  ('object-transfer-observation-m4_6', 'motor'::domain, 'm4_6'::age_band, 'Object Transfer Observation', 'A calm, close activity for building reflexive grasp.', 8, '5–10 min', 'Two small soft objects', 'Give a toy in one hand, then offer a second near the other. Do they transfer the first, or hold both? Transfer appears around 5–6 months.', 'Your baby''s hands are mostly working on reflex at this stage, and this gently invites them to open, feel and eventually grasp on purpose. At this age your only job is to offer it warmly and let your baby respond however they do; there is nothing to achieve and nothing to get right.', 'AOTA Early Development; AAP Developmental Milestones; IAP'),
  ('shake-listen-m4_6', 'motor'::domain, 'm4_6'::age_band, 'Shake Listen', 'A simple everyday moment that supports hand awareness and early grasp.', 8, '5–10 min', 'Sealed container with lentils', 'Hand baby a small sealed container (lid glued or taped shut) with dried lentils inside. Let them discover shaking makes sound: first voluntary cause-effect action. Never use an unsealed container with loose lentils at this age.', 'Hand movements are still involuntary now, so this is about sensation and awareness rather than skill. Repetition matters far more than variety now, so the same thing tomorrow is exactly right.', 'AOTA Early Development; AAP Developmental Milestones; IAP'),
  ('crinkle-paper-explore-m4_6', 'motor'::domain, 'm4_6'::age_band, 'Crinkle Paper Explore', 'A simple everyday moment that supports hand awareness and early grasp.', 8, '5–10 min', 'Baking paper or foil', 'Give a piece of crinkled paper or foil (supervised). The sound, texture, and visual feedback engage three senses simultaneously.', 'Hand movements are still involuntary now, so this is about sensation and awareness rather than skill. Keep it short and stop as soon as your baby looks away or fusses. Their attention span is measured in moments, and that is normal.', 'AOTA Early Development; AAP Developmental Milestones; IAP'),
  ('press-feel-m4_6', 'motor'::domain, 'm4_6'::age_band, 'Press Feel', 'A calm, close activity for building hand awareness and opening.', 8, '5–10 min', 'Various textured household surfaces', 'Press a textured surface gently against baby''s palm: a mesh bag, rough towel, smooth cup. The hand''s sensory map is being built now.', 'Hand movements are still involuntary now, so this is about sensation and awareness rather than skill. Keep it short and stop as soon as your baby looks away or fusses. Their attention span is measured in moments, and that is normal.', 'AOTA Early Development; AAP Developmental Milestones; IAP'),
  ('babble-echo-session-m4_6', 'communication'::domain, 'm4_6'::age_band, 'Babble Echo Session', 'A gentle activity that supports early vocal play.', 8, '5–10 min', 'None', 'When baby coos or babbles, echo it back exactly. Then add one new syllable: ''ooh… and then… ba?'' Pause 10 seconds each time.', 'Long before your baby says a word, they are learning the rhythm, pitch and melody of your language, and that learning happens now. At this age your only job is to offer it warmly and let your baby respond however they do; there is nothing to achieve and nothing to get right.', 'ASHA Speech and Language Milestones; Harvard Center on the Developing Child (Serve and Return); IAP'),
  ('makes-baby-laugh-m4_6', 'communication'::domain, 'm4_6'::age_band, 'Makes Baby Laugh', 'A simple everyday moment that supports early vocal play.', 8, '5–10 min', 'None', 'Try raspberry sounds, sudden peekaboo, lifting gently in the air. The belly laugh (appearing around 3–4 months) is a major milestone.', 'Your voice is the most important sound in your baby''s world, and every bit of talk builds the foundation for later language. Repetition matters far more than variety now, so the same thing tomorrow is exactly right.', 'ASHA Speech and Language Milestones; Harvard Center on the Developing Child (Serve and Return); IAP'),
  ('consonant-introduction-m4_6', 'communication'::domain, 'm4_6'::age_band, 'Consonant Introduction', 'A gentle activity that supports listening and early vocal play.', 7, '5–8 min', 'None', 'Model ba-ba-ba, ma-ma-ma, da-da-da during alert windows. These are the first consonants baby will produce at 5–6 months.', 'Your voice is the most important sound in your baby''s world, and every bit of talk builds the foundation for later language. Keep it short and stop as soon as your baby looks away or fusses. Their attention span is measured in moments, and that is normal.', 'ASHA Speech and Language Milestones; Harvard Center on the Developing Child (Serve and Return); IAP'),
  ('talk-both-languages-m4_6', 'communication'::domain, 'm4_6'::age_band, 'Talk Both Languages', 'A gentle activity that supports listening and voice recognition.', null, 'Ongoing', 'None', 'Speak in two languages fluidly during routines. ''Now we''re washing your hands: haath dho rahe hain.'' Bilingual input from birth is a gift.', 'Your voice is the most important sound in your baby''s world, and every bit of talk builds the foundation for later language. Keep it short and stop as soon as your baby looks away or fusses. Their attention span is measured in moments, and that is normal.', 'ASHA Speech and Language Milestones; Harvard Center on the Developing Child (Serve and Return); IAP'),
  ('photo-person-i-m4_6', 'communication'::domain, 'm4_6'::age_band, 'Photo Person I', 'A calm, close activity for building response to voice.', 4, '3–5 min', 'None', 'Point to each family member and say their name slowly. ''This is Dadi. Dadi.'' Repetition over weeks builds face-name recognition.', 'Your voice is the most important sound in your baby''s world, and every bit of talk builds the foundation for later language. At this age your only job is to offer it warmly and let your baby respond however they do; there is nothing to achieve and nothing to get right.', 'ASHA Speech and Language Milestones; Harvard Center on the Developing Child (Serve and Return); IAP'),
  ('music-variety-session-m4_6', 'communication'::domain, 'm4_6'::age_band, 'Music Variety Session', 'A calm, close activity for building early vocal play.', 8, '5–10 min', 'Phone or any music source', 'Play a different musical genre each day this week: classical, folk, jazz, film songs. Varied sound builds auditory discrimination.', 'Babies absorb the patterns of speech months before they can produce any of it, which is why talking to them matters so early. Repetition matters far more than variety now, so the same thing tomorrow is exactly right.', 'WHO Screen Time Guidelines (under 5); IAP Screen Time Guidance; IAP'),
  ('name-moving-m4_6', 'communication'::domain, 'm4_6'::age_band, 'Name: Moving', 'A calm, close activity for building response to voice.', 4, '3–5 min', 'None', 'Call baby''s name from different positions: behind, left, right. Turn-to-name appearing consistently by 6 months is a key milestone.', 'Long before your baby says a word, they are learning the rhythm, pitch and melody of your language, and that learning happens now. At this age your only job is to offer it warmly and let your baby respond however they do; there is nothing to achieve and nothing to get right.', 'ASHA Speech and Language Milestones; Harvard Center on the Developing Child (Serve and Return); IAP'),
  ('pause-song-m4_6', 'communication'::domain, 'm4_6'::age_band, 'Pause Song', 'A calm, close activity for building rhythm and melody of language.', 7, '5–8 min', 'None', 'Sing a familiar song and stop mid-verse. Wait. Watch baby''s face: anticipation appearing means they have learned the pattern.', 'Long before your baby says a word, they are learning the rhythm, pitch and melody of your language, and that learning happens now. Keep it short and stop as soon as your baby looks away or fusses. Their attention span is measured in moments, and that is normal.', 'ASHA Speech and Language Milestones; Harvard Center on the Developing Child (Serve and Return); IAP'),
  ('peekaboo-m4_6', 'cognitive'::domain, 'm4_6'::age_band, 'Peekaboo', 'A simple everyday moment that supports face recognition.', 7, '5–8 min', 'Cloth or book', 'While baby watches, slowly hide your face behind a cloth or book. Wait 5 seconds. Reveal. Object permanence for faces is appearing now.', 'Your baby''s brain is building its very first expectations about the world, mostly through what they see and hear repeatedly. At this age your only job is to offer it warmly and let your baby respond however they do; there is nothing to achieve and nothing to get right.', 'Piagetian developmental framework; Harvard Center on the Developing Child; IAP'),
  ('push-see-m4_6', 'cognitive'::domain, 'm4_6'::age_band, 'Push See', 'A calm, close activity for building visual attention and tracking.', 8, '5–10 min', 'Rattle or sealed container with lentils', 'Give baby a rattle. Let them discover that shaking = sound. When they look surprised after shaking, they have understood cause-effect.', 'Your baby''s brain is building its very first expectations about the world, mostly through what they see and hear repeatedly. At this age your only job is to offer it warmly and let your baby respond however they do; there is nothing to achieve and nothing to get right.', 'Harvard Center on the Developing Child; Zero to Three; IAP'),
  ('out-box-m4_6', 'cognitive'::domain, 'm4_6'::age_band, 'Out Box', 'A calm, close activity for building visual attention and early recognition.', 8, '5–10 min', 'Bowl and soft balls', 'Show baby how to put an object into a bowl and take it out. Let them try. In-out schema is foundational for spatial reasoning.', 'Your baby''s brain is building its very first expectations about the world, mostly through what they see and hear repeatedly. Repetition matters far more than variety now, so the same thing tomorrow is exactly right.', 'Harvard Center on the Developing Child; Zero to Three; IAP'),
  ('follow-my-point-m4_6', 'cognitive'::domain, 'm4_6'::age_band, 'Follow My Point', 'A calm, close activity for building visual attention and tracking.', 7, '5–8 min', 'None', 'Point at objects and then look at baby''s face: do they follow your point? Joint attention developing around 5–6 months.', 'Your baby''s brain is building its very first expectations about the world, mostly through what they see and hear repeatedly. Keep it short and stop as soon as your baby looks away or fusses. Their attention span is measured in moments, and that is normal.', 'Harvard Center on the Developing Child; Zero to Three; IAP'),
  ('smooth-texture-game-m4_6', 'cognitive'::domain, 'm4_6'::age_band, 'Smooth? Texture Game', 'A calm, close activity for building visual attention and early recognition.', 7, '5–8 min', 'Two textured household items', 'Give two very different textures simultaneously: smooth and rough. Let baby feel both and switch between them. Comparison is the lesson.', 'Your baby''s brain is building its very first expectations about the world, mostly through what they see and hear repeatedly. Repetition matters far more than variety now, so the same thing tomorrow is exactly right.', 'Harvard Center on the Developing Child; Zero to Three; IAP'),
  ('what-s-coming-game-m4_6', 'cognitive'::domain, 'm4_6'::age_band, 'What''s Coming Game', 'A simple everyday moment that supports visual attention and early recognition.', 8, '5–10 min', 'None', 'Do an action three times that baby enjoys: a raspberry, a bounce. On the fourth, pause before. Watch for anticipatory smile.', 'Newborn vision and attention are still developing, and this gives them exactly the kind of input that helps them along. At this age your only job is to offer it warmly and let your baby respond however they do; there is nothing to achieve and nothing to get right.', 'Harvard Center on the Developing Child; Zero to Three; IAP'),
  ('social-smile-response-m4_6', 'social_emotional'::domain, 'm4_6'::age_band, 'Social Smile Response', 'A gentle activity that supports early social connection.', null, 'Ongoing', 'None', 'Every time baby smiles, reflect it back immediately with warmth. Teaching: my positive emotion has social power. This builds communication.', 'Your baby cannot calm themselves yet, so being soothed by you is how their nervous system learns what calm feels like. Keep it short and stop as soon as your baby looks away or fusses. Their attention span is measured in moments, and that is normal.', 'Harvard Center on the Developing Child (Attachment); Zero to Three; UNICEF Responsive Caregiving; IAP'),
  ('stranger-presence-practice-m4_6', 'social_emotional'::domain, 'm4_6'::age_band, 'Stranger Presence Practice', 'A calm, close activity for building comfort and co-regulation.', 8, '5–10 min', 'None', 'When a new person is present, hold baby and engage the person warmly yourself. Baby reads your calm as: this person is safe.', 'Your baby cannot calm themselves yet, so being soothed by you is how their nervous system learns what calm feels like. At this age your only job is to offer it warmly and let your baby respond however they do; there is nothing to achieve and nothing to get right.', 'Harvard Center on the Developing Child (Attachment); Zero to Three; UNICEF Responsive Caregiving; IAP'),
  ('listening-no-m4_6', 'social_emotional'::domain, 'm4_6'::age_band, 'Listening No', 'A gentle activity that supports emotional tone recognition.', 4, '3–5 min', 'None', 'When baby shows displeasure at a game stopping, restart it. Teaching: expressing a feeling produces a response. Foundation of communication.', 'Every time you respond to your baby, you are teaching them that the world is reliable, which is the foundation of secure attachment. Repetition matters far more than variety now, so the same thing tomorrow is exactly right.', 'Harvard Center on the Developing Child (Attachment); Zero to Three; UNICEF Responsive Caregiving; IAP'),
  ('practising-goodbye-m4_6', 'social_emotional'::domain, 'm4_6'::age_band, 'Practising Goodbye', 'A calm, close activity for building trust through responsive care.', 2, '1–3 min', 'None', 'Step out of baby''s visual field for 30 seconds. Return before they cry. Gradually extend. Teaching: the person comes back.', 'This is the beginning of the relationship, and at this age closeness and responsiveness are the whole task. Repetition matters far more than variety now, so the same thing tomorrow is exactly right.', 'Harvard Center on the Developing Child (Attachment); Zero to Three; UNICEF Responsive Caregiving; IAP'),
  ('naming-feelings-m4_6', 'social_emotional'::domain, 'm4_6'::age_band, 'Naming Feelings', 'A simple everyday moment that supports early social connection.', null, 'Ongoing', 'None', 'Name emotions you see: ''You love that sound! Your face lit up.'' Accurate emotional labelling builds the brain''s emotional vocabulary.', 'Your baby cannot calm themselves yet, so being soothed by you is how their nervous system learns what calm feels like. Repetition matters far more than variety now, so the same thing tomorrow is exactly right.', 'Harvard Center on the Developing Child (Attachment); Zero to Three; UNICEF Responsive Caregiving; IAP'),
  ('look-this-together-m4_6', 'social_emotional'::domain, 'm4_6'::age_band, 'Look This Together', 'A simple everyday moment that supports comfort and co-regulation.', 7, '5–8 min', 'Any interesting object', 'Hold up an interesting object and look between it and baby''s face: object, baby, object. This is joint attention, a language precursor.', 'Every time you respond to your baby, you are teaching them that the world is reliable, which is the foundation of secure attachment. Repetition matters far more than variety now, so the same thing tomorrow is exactly right.', 'Harvard Center on the Developing Child (Attachment); Zero to Three; UNICEF Responsive Caregiving; IAP'),
  ('water-kicking-m4_6', 'cognitive'::domain, 'm4_6'::age_band, 'Water Kicking', 'A simple everyday moment that supports temperature and water sensation.', 13, '10–15 min', 'Water', 'Staying within arm''s reach throughout, let baby kick freely in the bath for 5 extra minutes. Water resistance builds leg strength while providing rich sensory feedback. Never leave baby unattended in water, even briefly.', 'Calm, predictable sensory input helps a young baby settle and regulate. Repetition matters far more than variety now, so the same thing tomorrow is exactly right.', 'AOTA Sensory Integration; AAP Developmental Milestones; IAP'),
  ('sensory-walk-m4_6', 'cognitive'::domain, 'm4_6'::age_band, 'Sensory Walk', 'A gentle activity that supports auditory processing.', 13, '10–15 min', 'None', 'Walk outside slowly, narrating each sensory experience: ''That''s wind on your face. Listen: that''s a crow.'' Multi-sensory saturation.', 'Calm, predictable sensory input helps a young baby settle and regulate. At this age your only job is to offer it warmly and let your baby respond however they do; there is nothing to achieve and nothing to get right.', 'AOTA Sensory Integration; AAP Developmental Milestones; IAP'),
  ('varied-food-textures-m4_6', 'cognitive'::domain, 'm4_6'::age_band, 'Varied Food Textures', 'A simple everyday moment that supports sensory input and regulation.', 13, '10–15 min', 'Food (purée)', 'If starting solids, introduce one very smooth purée at a time. Oral sensory exploration (taste and texture together) is its own skill.', 'Sensory experience is how a newborn learns about their own body and the world around it. Repetition matters far more than variety now, so the same thing tomorrow is exactly right.', 'WHO Complementary Feeding; IAP Infant and Young Child Feeding; ICMR-NIN; IAP'),
  ('dance-sway-m4_6', 'cognitive'::domain, 'm4_6'::age_band, 'Dance Sway', 'A gentle activity that supports auditory processing.', 8, '5–10 min', 'Any music', 'Hold baby and sway or dance to music with rhythm. Vestibular input plus auditory rhythm is two systems activating simultaneously.', 'Sensory experience is how a newborn learns about their own body and the world around it. Repetition matters far more than variety now, so the same thing tomorrow is exactly right.', 'AOTA Sensory Integration; AAP Developmental Milestones; IAP'),
  ('temperature-contrast-hands-m4_6', 'cognitive'::domain, 'm4_6'::age_band, 'Temperature Contrast Hands', 'A simple everyday moment that supports visual processing.', 4, '3–5 min', 'Cloths at different temperatures', 'Alternate placing a cool and slightly warm cloth against baby''s hands. Narrate each change. Temperature discrimination is developing.', 'Calm, predictable sensory input helps a young baby settle and regulate. Repetition matters far more than variety now, so the same thing tomorrow is exactly right.', 'AOTA Sensory Integration; AAP Developmental Milestones; IAP'),
  ('before-every-feed-m4_6', 'social_emotional'::domain, 'm4_6'::age_band, 'Before Every Feed', 'A calm, close activity for building feeding rhythm and hunger cues.', null, 'Ongoing', 'None', 'Establish a consistent pre-feed sequence (dim lights, hold position, a specific phrase). Predictability regulates baby''s anticipatory state.', 'At this age self-care is entirely done for your baby, and the value lies in how calm and consistent it feels. Keep it short and stop as soon as your baby looks away or fusses. Their attention span is measured in moments, and that is normal.', 'IAP Infant Care Guidance; UNICEF Responsive Caregiving; IAP'),
  ('before-every-nap-m4_6', 'social_emotional'::domain, 'm4_6'::age_band, 'Before Every Nap', 'A gentle activity that supports feeding rhythm and hunger cues.', 13, '10–15 min', 'Swaddle or sleep sack', 'Same 3–4 steps before every nap: swaddle/sleep sack, darken room, white noise, feed. Consistent cues train the brain to prepare for sleep.', 'Daily care routines are your baby''s first experience of predictability, and predictability is what makes them feel safe. Keep it short and stop as soon as your baby looks away or fusses. Their attention span is measured in moments, and that is normal.', 'AAP Safe Sleep Guidance; IAP; IAP'),
  ('sitting-balance-challenge-m7_9', 'motor'::domain, 'm7_9'::age_band, 'Sitting Balance Challenge', 'A playful activity that builds sitting balance.', 8, '5–10 min', 'Toy', 'Sit baby on firm surface. Place a toy slightly to the side so they must lean to reach. Each topple-and-catch is a core strength exercise.', 'This is the stage where babies begin to move themselves through the world, and every attempt builds the strength for the next milestone. Follow your baby''s lead and let them take the activity where they want it; their interest is what makes it stick.', 'WHO Motor Development Milestones; AAP Physical Activity; IAP'),
  ('crawling-encouragement-m7_9', 'motor'::domain, 'm7_9'::age_band, 'Crawling Encouragement', 'A short, repeatable activity that supports crawling and cross-body coordination.', 8, '5–10 min', 'Toy', 'Place a desirable toy 50 cm in front of baby on the floor. Stay beside or behind (not in front) so they crawl away from you.', 'Your baby is learning what their body can do, and the falls and wobbles are part of how that map gets built. Keep it playful and stop before frustration arrives; a short happy attempt beats a long difficult one.', 'WHO Motor Development Milestones; AAP Physical Activity; IAP'),
  ('all-fours-rocking-m7_9', 'motor'::domain, 'm7_9'::age_band, 'All-Fours Rocking', 'A hands-on activity for developing crawling and cross-body coordination.', 8, '5–10 min', 'Toy', 'Place baby on hands and knees (support if needed). Place a toy just out of reach. Watch for rocking: the crawl motor pattern loading.', 'This is the stage where babies begin to move themselves through the world, and every attempt builds the strength for the next milestone. Expect a great deal of repetition, because repeating something is how babies this age master it.', 'WHO Motor Development Milestones; AAP Physical Activity; IAP'),
  ('obstacle-crawl-m7_9', 'motor'::domain, 'm7_9'::age_band, 'Obstacle Crawl', 'A short, repeatable activity that supports crawling and cross-body coordination.', 13, '10–15 min', 'Rolled blanket', 'Place a rolled blanket or sofa cushion in the crawl path. Watch whether baby navigates around or over it. Motor problem-solving.', 'This is the stage where babies begin to move themselves through the world, and every attempt builds the strength for the next milestone. Expect a great deal of repetition, because repeating something is how babies this age master it.', 'WHO Motor Development Milestones; AAP Physical Activity; IAP'),
  ('pull-stand-m7_9', 'motor'::domain, 'm7_9'::age_band, 'Pull Stand', 'A short, repeatable activity that supports pulling to stand and leg strength.', 8, '5–10 min', 'Low furniture + toy', 'Position baby next to a stable low piece of furniture. Place a toy on the surface above their head. Support at hips, not hands.', 'Crawling, pulling up and cruising all arrive in this window, and they arrive through practice rather than instruction. Follow your baby''s lead and let them take the activity where they want it; their interest is what makes it stick.', 'WHO Motor Development Milestones; AAP Physical Activity; IAP'),
  ('pivot-tummy-time-m7_9', 'motor'::domain, 'm7_9'::age_band, 'Pivot Tummy Time', 'A playful activity that builds crawling and cross-body coordination.', 8, '5–10 min', 'Toy', 'Place a toy at 45° from baby in tummy time. Watch them pivot their body to follow. This uses the same muscles as crawling.', 'This is the stage where babies begin to move themselves through the world, and every attempt builds the strength for the next milestone. Expect a great deal of repetition, because repeating something is how babies this age master it.', 'AAP Safe Sleep and Tummy Time; WHO Motor Development; IAP'),
  ('walking-hold-m7_9', 'motor'::domain, 'm7_9'::age_band, 'Walking Hold', 'A short, repeatable activity that supports cruising and first steps.', 8, '5–10 min', 'None', 'Hold both of baby''s hands from behind and let them walk forward at their own pace. Alternate to one hand as confidence grows.', 'Your baby is learning what their body can do, and the falls and wobbles are part of how that map gets built. Expect a great deal of repetition, because repeating something is how babies this age master it.', 'WHO Motor Development Milestones; AAP Physical Activity; IAP'),
  ('stair-climbing-m7_9', 'motor'::domain, 'm7_9'::age_band, 'Stair Climbing', 'A short, repeatable activity that supports crawling and cross-body coordination.', 8, '5–10 min', 'Stairs', 'Let baby crawl up 2–3 safe stairs with you directly behind. Stair climbing builds strength, coordination, and spatial awareness.', 'Your baby is learning what their body can do, and the falls and wobbles are part of how that map gets built. Keep it playful and stop before frustration arrives; a short happy attempt beats a long difficult one.', 'WHO Motor Development Milestones; AAP Physical Activity; IAP'),
  ('pinch-pick-up-m7_9', 'motor'::domain, 'm7_9'::age_band, 'Pinch Pick Up', 'A short, repeatable activity that supports early pincer grasp.', 8, '5–10 min', 'Puffed snack or small safe object', 'Place large puffed snacks or safe small objects on a tray. Watch how they pick up: raking grasp transitioning to pincer grasp.', 'The finger and thumb grip that will later hold a spoon and a pencil begins forming in this window. Expect a great deal of repetition, because repeating something is how babies this age master it.', 'AOTA Early Development; AAP Developmental Milestones; IAP'),
  ('object-container-m7_9', 'motor'::domain, 'm7_9'::age_band, 'Object Container', 'A playful activity that builds voluntary release.', 8, '5–10 min', 'Bowl and soft objects', 'Give a large container and 4–5 objects. Let baby drop them in and dump them out repeatedly. Foundational spatial reasoning.', 'Your baby is learning to let go on purpose, which is a genuinely harder skill than picking something up. Keep it playful and stop before frustration arrives; a short happy attempt beats a long difficult one.', 'AOTA Early Development; AAP Developmental Milestones; IAP'),
  ('banging-objects-together-m7_9', 'motor'::domain, 'm7_9'::age_band, 'Banging Objects Together', 'A hands-on activity for developing grasp and release with purpose.', 8, '5–10 min', 'Two safe household objects', 'Give two objects and demonstrate banging them together. When baby copies, bilateral motor coordination and cause-effect are both working.', 'This is when grasping becomes deliberate rather than reflexive, and every reach and release is practice. Keep it playful and stop before frustration arrives; a short happy attempt beats a long difficult one.', 'AOTA Early Development; AAP Developmental Milestones; IAP'),
  ('page-turning-m7_9', 'motor'::domain, 'm7_9'::age_band, 'Page Turning', 'A short, repeatable activity that supports page turning and finger isolation.', 7, '5–8 min', 'Board book', 'Offer a board book and let baby try to turn pages. Even clumsy turning is fine motor skill and book engagement combined.', 'This is when grasping becomes deliberate rather than reflexive, and every reach and release is practice. Keep it playful and stop before frustration arrives; a short happy attempt beats a long difficult one.', 'AOTA Early Development; AAP Developmental Milestones; IAP'),
  ('stack-topple-m7_9', 'motor'::domain, 'm7_9'::age_band, 'Stack Topple', 'A short, repeatable activity that supports voluntary grasp and release.', 8, '5–10 min', 'Blocks or similar stackable objects', 'Stack 2 blocks, let baby knock them over. The knock is as developmental as the build: cause-effect with a satisfying outcome.', 'This is when grasping becomes deliberate rather than reflexive, and every reach and release is practice. Expect a great deal of repetition, because repeating something is how babies this age master it.', 'AOTA Early Development; AAP Developmental Milestones; IAP'),
  ('between-two-containers-m7_9', 'motor'::domain, 'm7_9'::age_band, 'Between Two Containers', 'A hands-on activity for developing voluntary release.', 8, '5–10 min', 'Two bowls + objects', 'Show baby how to move an object from one bowl to another. This requires spatial planning and goal-directed motor action.', 'This is when grasping becomes deliberate rather than reflexive, and every reach and release is practice. Keep it playful and stop before frustration arrives; a short happy attempt beats a long difficult one.', 'AOTA Early Development; AAP Developmental Milestones; IAP'),
  ('echo-baby-s-babbling-m7_9', 'communication'::domain, 'm7_9'::age_band, 'Echo Baby''s Babbling', 'A hands-on activity for developing babbling and sound imitation.', 8, '5–10 min', 'None', 'When baby produces ba-ba, da-da, or ma-ma, echo immediately and expand: ''Ba ba ba! And then: da da da?'' Pause 10 seconds.', 'Understanding runs well ahead of speaking at this age, and this builds the comprehension that first words will grow from. Expect a great deal of repetition, because repeating something is how babies this age master it.', 'ASHA Speech and Language Milestones; Harvard Center on the Developing Child (Serve and Return); IAP'),
  ('respond-name-m7_9', 'communication'::domain, 'm7_9'::age_band, 'Respond Name', 'A playful activity that builds understanding first words.', 4, '3–5 min', 'None', 'Test: call baby''s name from 2 m away in a normal voice. Consistent response by 9 months is a key language milestone.', 'This is the window where gestures and sounds start carrying meaning, which is language beginning. Keep it playful and stop before frustration arrives; a short happy attempt beats a long difficult one.', 'ASHA Speech and Language Milestones; Harvard Center on the Developing Child (Serve and Return); IAP'),
  ('gesture-introduction-m7_9', 'communication'::domain, 'm7_9'::age_band, 'Gesture Introduction', 'A playful activity that builds pre-verbal communication (gesture).', null, 'Ongoing', 'None', 'Wave goodbye every single time anyone leaves. Every time, consistently. First gestural communication appears 8–10 months.', 'Babbling is real practice for speech, and responding to it teaches your baby that sounds get answers. Follow your baby''s lead and let them take the activity where they want it; their interest is what makes it stick.', 'ASHA Speech and Language Milestones; Harvard Center on the Developing Child (Serve and Return); IAP'),
  ('point-name-m7_9', 'communication'::domain, 'm7_9'::age_band, 'Point Name', 'A short, repeatable activity that supports understanding first words.', null, 'Ongoing', 'None', 'Point at objects throughout the day and name them. When baby points at something, immediately name it and comment.', 'Babbling is real practice for speech, and responding to it teaches your baby that sounds get answers. Follow your baby''s lead and let them take the activity where they want it; their interest is what makes it stick.', 'ASHA Speech and Language Milestones; Harvard Center on the Developing Child (Serve and Return); IAP')
